use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::BTreeMap,fs,io::Read,path::Path};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn copy(src:&Path,dst:&Path){fs::create_dir_all(dst.parent().unwrap()).unwrap();fs::copy(src,dst).unwrap();}
fn save(p:impl AsRef<Path>,v:Value){fs::write(p,format!("{}\n",serde_json::to_string_pretty(&v).unwrap())).unwrap()}
fn main(){let root=Path::new("/tmp/zopro-outlined-snapshot-fence");let parent=Path::new("/tmp/zopro-front-snapshot-fence");let mode=std::env::args().nth(1).unwrap();if mode=="overlay"{assert!(!root.join("overlay").exists());let prep=read(parent.join("prepare.json"));for(p,h)in prep["overlay_files"].as_object().unwrap(){let src=parent.join("candidate").join(p);assert_eq!(hash(&src),h.as_str().unwrap());copy(&src,&root.join("overlay").join(p));}let path=root.join("overlay/vendor/rayon-core-1.13.0/src/registry/front_snapshot.rs");let old=fs::read_to_string(&path).unwrap();let anchor="    pub(super) fn steal_front_snapshot_tiles(&self) -> Option<JobRef> {";assert_eq!(old.matches(anchor).count(),1);fs::write(path,old.replace(anchor,&format!("    #[inline(never)]\n{anchor}"))).unwrap();for p in ["model/Cargo.toml","model/Cargo.lock","model/src/lib.rs","upstream-deque.rs","upstream-registry.rs","upstream-pins.json","lock-audit.json","ordering-review.md"]{copy(&parent.join(p),&root.join(p));}let audit=fs::read_to_string(parent.join("source-audit.rs")).unwrap().replace("/tmp/zopro-front-snapshot-fence","/tmp/zopro-outlined-snapshot-fence");fs::write(root.join("source-audit.rs"),audit).unwrap();copy(&parent.join("accepted-manifest.json"),&root.join("accepted-manifest.json"));save(root.join("parent-source-pins.json"),read(parent.join("candidate/.xtask/source-pins.json")));println!("Overlay copied from frozen parent; exactly one inline(never) attribute added");return;}
assert_eq!(mode,"build-plan");let parent_pins=read(root.join("parent-source-pins.json"));let candidate_pins=read(root.join("candidate/.xtask/source-pins.json"));assert_eq!(parent_pins.as_object().unwrap().len(),232);assert_eq!(candidate_pins.as_object().unwrap().len(),232);let target="vendor/rayon-core-1.13.0/src/registry/front_snapshot.rs";let mut changed=Vec::new();for(p,h)in parent_pins.as_object().unwrap(){let relative=Path::new(p).strip_prefix(parent.join("candidate")).unwrap();let new=root.join("candidate").join(relative);assert_eq!(hash(p),h.as_str().unwrap());let actual=hash(&new);assert_eq!(actual,candidate_pins[new.to_str().unwrap()].as_str().unwrap());if actual!=h.as_str().unwrap(){assert_eq!(relative,Path::new(target));let s=fs::read_to_string(&new).unwrap();assert_eq!(s.matches("    #[inline(never)]\n").count(),1);assert_eq!(s.replacen("    #[inline(never)]\n","",1),fs::read_to_string(p).unwrap());changed.push(relative.to_str().unwrap().to_owned());}}assert_eq!(changed.len(),1);for p in ["model/Cargo.toml","model/Cargo.lock","model/src/lib.rs"]{assert_eq!(fs::read(root.join(p)).unwrap(),fs::read(parent.join(p)).unwrap());}save(root.join("outline-audit.json"),json!({"status":"passed","prepared_files":232,"byte_identical_files":231,"changed":changed,"delta":"exactly one #[inline(never)] attribute; deleting it recovers the full original source byte-for-byte","unchanged_models":5,"meaning":"No algorithm/queue/guard/fence/retry/first-probe/tile/kernel/representation/dependency change; codegen gate still required"}));let old=fs::read_to_string(parent.join("native-plan.json")).unwrap().replace("/tmp/zopro-front-snapshot-fence","/tmp/zopro-outlined-snapshot-fence");let mut plan:Value=serde_json::from_str(&old).unwrap();plan["source_pins"]=json!(root.join("build-input-pins.json"));let mut pins:BTreeMap<String,String>=serde_json::from_value(candidate_pins).unwrap();for(p,h)in parent_pins.as_object().unwrap(){pins.insert(p.into(),h.as_str().unwrap().into());}for p in ["experiment.json","prepare.rs","prepare.json","source-audit.rs","source-audit.json","outline-audit.json","parent-source-pins.json","model/Cargo.toml","model/Cargo.lock","model/src/lib.rs","upstream-deque.rs","upstream-registry.rs","upstream-pins.json","lock-audit.json","ordering-review.md"]{let path=root.join(p);pins.insert(path.to_str().unwrap().into(),hash(path));}for(p,h)in read(root.join("upstream-pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pins.insert(p.into(),h.as_str().unwrap().into());}let tool="/home/ubuntu/src/zk-tools/zopro/xtask/target/release/xtask";pins.insert(tool.into(),hash(tool));save(root.join("build-input-pins.json"),json!(pins));save(root.join("native-plan.json"),plan);println!("FROZEN build{}pins;231/232sourcefiles identical and remainingfile differs only by attribute",pins.len());}
